import React, { useState, useEffect } from "react";
import { useParams, useNavigate } from "react-router-dom";
import axios from "axios";

const states = [
  "Andhra Pradesh", "Arunachal Pradesh", "Assam", "Bihar", "Chhattisgarh",
  "Goa", "Gujarat", "Haryana", "Himachal Pradesh", "Jharkhand", "Karnataka",
  "Kerala", "Madhya Pradesh", "Maharashtra", "Manipur", "Meghalaya", "Mizoram",
  "Nagaland", "Odisha", "Punjab", "Rajasthan", "Sikkim", "Tamil Nadu",
  "Telangana", "Tripura", "Uttar Pradesh", "Uttarakhand", "West Bengal",
  "Jammu and Kashmir"
];

export default function ApplyForm() {
  const { id } = useParams();
  const navigate = useNavigate();
  const [job, setJob] = useState(null);
  const [loading, setLoading] = useState(false);
  const [resumeFile, setResumeFile] = useState(null);
  const [uploadProgress, setUploadProgress] = useState(0);
  const [extracting, setExtracting] = useState(false);
  const [extractionComplete, setExtractionComplete] = useState(false);

  const [formData, setFormData] = useState({
    name: "",
    email: "",
    phone: "",
    skillset: "",
    state: "",
    city: "",
    pincode: "",
    address: "",
    project: "",
    tenth: "",
    tenthSchool: "",
    diploma: "",
    diplomaCollege: "",
    diplomaStream: "",
    graduation: "",
    graduationCollege: "",
    graduationStream: "",
    postGraduation: "",
    postGraduationCollege: "",
    postGraduationStream: "",
    internships: "",
  });

  useEffect(() => {
    fetchJobDetails();
  }, [id]);

  const fetchJobDetails = async () => {
    try {
      const response = await axios.get("http://localhost:5000/api/jobs");
      const foundJob = response.data.find((j) => j._id === id);
      if (foundJob) {
        setJob(foundJob);
      }
    } catch (err) {
      console.error("Error fetching job:", err);
    }
  };

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData({ ...formData, [name]: value });
  };

  const handleFileChange = (e) => {
    const file = e.target.files[0];
    if (file) {
      if (file.type !== "application/pdf") {
        alert("Please upload only PDF files!");
        e.target.value = "";
        return;
      }
      if (file.size > 5 * 1024 * 1024) {
        alert("File size should be less than 5MB!");
        e.target.value = "";
        return;
      }
      setResumeFile(file);
      setExtractionComplete(false);
    }
  };

  const handleResumeUploadAndExtract = async () => {
    if (!resumeFile) {
      alert("Please select a resume file first!");
      return;
    }

    const formDataToSend = new FormData();
    formDataToSend.append("resume", resumeFile);

    setExtracting(true);
    setUploadProgress(0);

    try {
      const response = await axios.post(
        "http://localhost:5000/api/extract-resume",
        formDataToSend,
        {
          headers: { "Content-Type": "multipart/form-data" },
          onUploadProgress: (progressEvent) => {
            const progress = Math.round(
              (progressEvent.loaded * 100) / progressEvent.total
            );
            setUploadProgress(progress);
          },
        }
      );

      if (response.data.success) {
        const extracted = response.data.data;

        // Auto-fill the form with extracted data
        setFormData({
          ...formData,
          name: extracted.name || formData.name,
          email: extracted.email || formData.email,
          phone: extracted.phone || formData.phone,
          skillset: extracted.skills?.join(", ") || formData.skillset,
          project: extracted.projects || formData.project,
          internships: extracted.internships || formData.internships,
          tenth: extracted.education?.tenth?.score || formData.tenth,
          tenthSchool: extracted.education?.tenth?.school || formData.tenthSchool,
          diploma: extracted.education?.diploma?.score || formData.diploma,
          diplomaCollege: extracted.education?.diploma?.college || formData.diplomaCollege,
          diplomaStream: extracted.education?.diploma?.stream || formData.diplomaStream,
          graduation: extracted.education?.graduation?.score || formData.graduation,
          graduationCollege: extracted.education?.graduation?.college || formData.graduationCollege,
          graduationStream: extracted.education?.graduation?.stream || formData.graduationStream,
          postGraduation: extracted.education?.postGraduation?.score || formData.postGraduation,
          postGraduationCollege: extracted.education?.postGraduation?.college || formData.postGraduationCollege,
          postGraduationStream: extracted.education?.postGraduation?.stream || formData.postGraduationStream,
        });

        setExtractionComplete(true);
        alert("✅ Resume extracted successfully! Please review and edit the auto-filled information.");
      }
    } catch (err) {
      console.error("Error extracting resume:", err);
      alert("Failed to extract resume data. Please fill the form manually or try again.");
    } finally {
      setExtracting(false);
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    if (!resumeFile) {
      alert("Please upload your resume!");
      return;
    }

    if (!formData.name || !formData.email || !formData.phone || !formData.skillset || 
        !formData.state || !formData.city || !formData.pincode || !formData.address ||
        !formData.tenth || !formData.tenthSchool || !formData.diploma || 
        !formData.diplomaCollege || !formData.diplomaStream || !formData.graduation || 
        !formData.graduationCollege || !formData.graduationStream || !formData.project) {
      alert("Please fill all required fields marked with *!");
      return;
    }

    const submitData = new FormData();
    submitData.append("resume", resumeFile);
    submitData.append("name", formData.name);
    submitData.append("email", formData.email);
    submitData.append("phone", formData.phone);
    submitData.append("skillset", formData.skillset);
    submitData.append("jobId", id);
    submitData.append("jobTitle", job?.title || "NA");
    submitData.append("location", `${formData.city}, ${formData.state}`);
    submitData.append("pincode", formData.pincode);
    submitData.append("address", formData.address);
    submitData.append("project", formData.project);
    submitData.append("internships", formData.internships);
    submitData.append("academic", JSON.stringify({
      tenth: { score: formData.tenth, school: formData.tenthSchool },
      diploma: { score: formData.diploma, college: formData.diplomaCollege, stream: formData.diplomaStream },
      graduation: { score: formData.graduation, college: formData.graduationCollege, stream: formData.graduationStream },
      postGraduation: { score: formData.postGraduation, college: formData.postGraduationCollege, stream: formData.postGraduationStream },
    }));

    setLoading(true);
    try {
      await axios.post("http://localhost:5000/api/applications", submitData, {
        headers: { "Content-Type": "multipart/form-data" },
      });
      alert("Application submitted successfully! We'll review your application and get back to you soon.");
      navigate("/");
    } catch (err) {
      console.error("Error submitting application:", err);
      alert("Failed to submit application. Please try again.");
    }
    setLoading(false);
  };

  if (!job) {
    return (
      <div style={styles.loadingContainer}>
        <div style={styles.loader}></div>
        <p>Loading application form...</p>
      </div>
    );
  }

  return (
    <div style={styles.page}>
      <div style={styles.container}>
        <div style={styles.header}>
          <button style={styles.backBtn} onClick={() => navigate(`/job/${id}`)}>
            ← Back to Job Details
          </button>
        </div>

        <div style={styles.formWrapper}>
          {/* Sidebar */}
          <div style={styles.sidebar}>
            <div style={styles.jobInfoCard}>
              <div style={styles.badge}>Now Hiring</div>
              <h3 style={styles.jobTitle}>{job.title}</h3>
              <p style={styles.jobRole}>{job.role}</p>

              <div style={styles.divider}></div>

              <div style={styles.infoSection}>
                <h4 style={styles.sidebarTitle}>Position Details</h4>
                <div style={styles.detailItem}>
                  <span style={styles.detailLabel}>Location</span>
                  <span style={styles.detailValue}>{job.location}</span>
                </div>
                <div style={styles.detailItem}>
                  <span style={styles.detailLabel}>Experience</span>
                  <span style={styles.detailValue}>{job.experience}</span>
                </div>
                <div style={styles.detailItem}>
                  <span style={styles.detailLabel}>Salary Range</span>
                  <span style={styles.detailValue}>{job.ctc}</span>
                </div>
              </div>

              <div style={styles.divider}></div>

              <div style={styles.infoSection}>
                <h4 style={styles.sidebarTitle}>Required Skills</h4>
                <div style={styles.skillsList}>
                  {job.skillset.split(",").map((skill, i) => (
                    <span key={i} style={styles.skillBadge}>{skill.trim()}</span>
                  ))}
                </div>
              </div>
            </div>
          </div>

          {/* Main Form */}
          <div style={styles.formContainer}>
            <h2 style={styles.formTitle}>Apply for this Position</h2>
            <p style={styles.formSubtitle}>Upload your resume and let AI auto-fill your details</p>

            <form onSubmit={handleSubmit} style={styles.form}>
              {/* AI Resume Upload Section */}
              <div style={styles.aiSection}>
                <div style={styles.aiHeader}>
                  <div style={styles.aiIconWrapper}>
                    <span style={styles.aiIcon}>🤖</span>
                  </div>
                  <div>
                    <h3 style={styles.aiTitle}>AI-Powered Resume Parser</h3>
                    <p style={styles.aiSubtitle}>Upload your resume and we'll extract information automatically</p>
                  </div>
                </div>

                <div style={styles.uploadBox}>
                  <input
                    type="file"
                    accept=".pdf"
                    onChange={handleFileChange}
                    style={styles.fileInput}
                    id="resume-upload"
                  />
                  <label htmlFor="resume-upload" style={styles.uploadLabel}>
                    <div style={styles.uploadIcon}>📄</div>
                    <div style={styles.uploadText}>
                      {resumeFile ? (
                        <>
                          <span style={styles.fileName}>{resumeFile.name}</span>
                          <span style={styles.fileSize}>
                            ({(resumeFile.size / 1024).toFixed(2)} KB)
                          </span>
                        </>
                      ) : (
                        <>
                          <span style={styles.uploadMainText}>Click to upload PDF resume</span>
                          <span style={styles.uploadSubText}>Maximum size: 5MB</span>
                        </>
                      )}
                    </div>
                  </label>
                </div>

                {resumeFile && (
                  <button
                    type="button"
                    onClick={handleResumeUploadAndExtract}
                    style={{...styles.extractBtn, opacity: extracting ? 0.7 : 1}}
                    disabled={extracting}
                  >
                    {extracting ? (
                      <>
                        <span style={styles.spinner}></span>
                        Extracting data... {uploadProgress}%
                      </>
                    ) : extractionComplete ? (
                      <>✅ Extraction Complete - Review Below</>
                    ) : (
                      <>🚀 Extract Data with AI</>
                    )}
                  </button>
                )}

                {extracting && (
                  <div style={styles.progressBar}>
                    <div style={{...styles.progressFill, width: `${uploadProgress}%`}}></div>
                  </div>
                )}

                {extractionComplete && (
                  <div style={styles.successBox}>
                    <span style={styles.successIcon}>✅</span>
                    <span style={styles.successText}>
                      Data extracted! Please review and edit below.
                    </span>
                  </div>
                )}
              </div>

              {/* Personal Information */}
              <div style={styles.sectionHeader}>
                <h3 style={styles.sectionTitle}>Personal Information</h3>
              </div>

              <div style={styles.inputGroup}>
                <label style={styles.label}>Full Name <span style={styles.required}>*</span></label>
                <input type="text" name="name" value={formData.name} onChange={handleChange} style={styles.input} placeholder="Enter your full name" required />
              </div>

              <div style={styles.inputRow}>
                <div style={styles.inputGroup}>
                  <label style={styles.label}>Email <span style={styles.required}>*</span></label>
                  <input type="email" name="email" value={formData.email} onChange={handleChange} style={styles.input} placeholder="your.email@example.com" required />
                </div>
                <div style={styles.inputGroup}>
                  <label style={styles.label}>Phone <span style={styles.required}>*</span></label>
                  <input type="tel" name="phone" value={formData.phone} onChange={handleChange} style={styles.input} placeholder="Phone number" required />
                </div>
              </div>

              <div style={styles.inputGroup}>
                <label style={styles.label}>Skillset <span style={styles.required}>*</span></label>
                <input 
                  type="text" 
                  name="skillset" 
                  value={formData.skillset} 
                  onChange={handleChange} 
                  style={styles.input} 
                  placeholder="React, JavaScript, Node.js, etc." 
                  required 
                />
              </div>

              {/* Location Details */}
              <div style={styles.sectionHeader}>
                <h3 style={styles.sectionTitle}>Location Details</h3>
              </div>

              <div style={styles.inputRow}>
                <div style={styles.inputGroup}>
                  <label style={styles.label}>State <span style={styles.required}>*</span></label>
                  <select name="state" value={formData.state} onChange={handleChange} style={styles.input} required>
                    <option value="">Select State</option>
                    {states.map((st) => (<option key={st} value={st}>{st}</option>))}
                  </select>
                </div>
                <div style={styles.inputGroup}>
                  <label style={styles.label}>City <span style={styles.required}>*</span></label>
                  <input type="text" name="city" value={formData.city} onChange={handleChange} style={styles.input} placeholder="City/Village" required />
                </div>
              </div>

              <div style={styles.inputRow}>
                <div style={styles.inputGroup}>
                  <label style={styles.label}>Pincode <span style={styles.required}>*</span></label>
                  <input type="text" name="pincode" value={formData.pincode} onChange={handleChange} style={styles.input} placeholder="Pincode" required />
                </div>
                <div style={styles.inputGroup}>
                  <label style={styles.label}>Address <span style={styles.required}>*</span></label>
                  <input type="text" name="address" value={formData.address} onChange={handleChange} style={styles.input} placeholder="Permanent address" required />
                </div>
              </div>

              {/* Academic Details */}
              <div style={styles.sectionHeader}>
                <h3 style={styles.sectionTitle}>Academic Details</h3>
              </div>

              <div style={styles.academicSection}>
                <h4 style={styles.academicTitle}>10th Standard</h4>
                <div style={styles.inputRow}>
                  <div style={styles.inputGroup}>
                    <label style={styles.label}>Score <span style={styles.required}>*</span></label>
                    <input type="text" name="tenth" value={formData.tenth} onChange={handleChange} style={styles.input} placeholder="85%" required />
                  </div>
                  <div style={styles.inputGroup}>
                    <label style={styles.label}>School <span style={styles.required}>*</span></label>
                    <input type="text" name="tenthSchool" value={formData.tenthSchool} onChange={handleChange} style={styles.input} placeholder="School name" required />
                  </div>
                </div>
              </div>

              <div style={styles.academicSection}>
                <h4 style={styles.academicTitle}>12th / Diploma</h4>
                <div style={styles.inputRow}>
                  <div style={styles.inputGroup}>
                    <label style={styles.label}>Score <span style={styles.required}>*</span></label>
                    <input type="text" name="diploma" value={formData.diploma} onChange={handleChange} style={styles.input} placeholder="80%" required />
                  </div>
                  <div style={styles.inputGroup}>
                    <label style={styles.label}>College <span style={styles.required}>*</span></label>
                    <input type="text" name="diplomaCollege" value={formData.diplomaCollege} onChange={handleChange} style={styles.input} placeholder="College name" required />
                  </div>
                </div>
                <div style={styles.inputGroup}>
                  <label style={styles.label}>Stream <span style={styles.required}>*</span></label>
                  <input type="text" name="diplomaStream" value={formData.diplomaStream} onChange={handleChange} style={styles.input} placeholder="Science/Commerce" required />
                </div>
              </div>

              <div style={styles.academicSection}>
                <h4 style={styles.academicTitle}>Graduation</h4>
                <div style={styles.inputRow}>
                  <div style={styles.inputGroup}>
                    <label style={styles.label}>Score <span style={styles.required}>*</span></label>
                    <input type="text" name="graduation" value={formData.graduation} onChange={handleChange} style={styles.input} placeholder="8.5 CGPA" required />
                  </div>
                  <div style={styles.inputGroup}>
                    <label style={styles.label}>College <span style={styles.required}>*</span></label>
                    <input type="text" name="graduationCollege" value={formData.graduationCollege} onChange={handleChange} style={styles.input} placeholder="College name" required />
                  </div>
                </div>
                <div style={styles.inputGroup}>
                  <label style={styles.label}>Stream <span style={styles.required}>*</span></label>
                  <input type="text" name="graduationStream" value={formData.graduationStream} onChange={handleChange} style={styles.input} placeholder="Computer Science" required />
                </div>
              </div>

              <div style={styles.academicSection}>
                <h4 style={styles.academicTitle}>Post Graduation (Optional)</h4>
                <div style={styles.inputRow}>
                  <div style={styles.inputGroup}>
                    <label style={styles.label}>Score</label>
                    <input type="text" name="postGraduation" value={formData.postGraduation} onChange={handleChange} style={styles.input} placeholder="8.0 CGPA" />
                  </div>
                  <div style={styles.inputGroup}>
                    <label style={styles.label}>College</label>
                    <input type="text" name="postGraduationCollege" value={formData.postGraduationCollege} onChange={handleChange} style={styles.input} placeholder="College name" />
                  </div>
                </div>
                <div style={styles.inputGroup}>
                  <label style={styles.label}>Stream</label>
                  <input type="text" name="postGraduationStream" value={formData.postGraduationStream} onChange={handleChange} style={styles.input} placeholder="M.Tech CS" />
                </div>
              </div>

              {/* Additional Information */}
              <div style={styles.sectionHeader}>
                <h3 style={styles.sectionTitle}>Additional Information</h3>
              </div>

              <div style={styles.inputGroup}>
                <label style={styles.label}>Projects <span style={styles.required}>*</span></label>
                <textarea name="project" value={formData.project} onChange={handleChange} style={{...styles.input, minHeight: "100px"}} placeholder="Describe your projects..." required />
              </div>

              <div style={styles.inputGroup}>
                <label style={styles.label}>Internships</label>
                <textarea name="internships" value={formData.internships} onChange={handleChange} style={{...styles.input, minHeight: "80px"}} placeholder="Describe internships..." />
              </div>

              <button type="submit" style={{...styles.submitBtn, opacity: loading ? 0.7 : 1}} disabled={loading}>
                {loading ? "Submitting..." : "Submit Application"}
              </button>
            </form>
          </div>
        </div>
      </div>
    </div>
  );
}

